  Lemma mm_fr1 : forall (xs : list Segment) (xm : word -> option byte) (xlo xb xp xhi : Z) (xw : word) (xj : list byte),
    rw_cells xs xm xb [C8 xw; CB 144 xj] -> stk xs xm xlo xb ->
    xp = xb \/ xp = xb - 16 -> xlo <= xp -> xhi = xb + 152 ->
    exists k0 k8 k16 k24 k32 k40 k48 k56 k64 k72 k80 k88 k96 k104 k112 k120 k144 : word,
      rw_cells xs xm xp [C8 k0; C8 k8; C8 k16; C8 k24; C8 k32; C8 k40; C8 k48; C8 k56; C8 k64; C8 k72; C8 k80; C8 k88; C8 k96; C8 k104; C8 k112; C8 k120] /\
      rw_cells xs xm (xp + 144) [C8 k144] /\ stk xs xm (xp + 128) (xp + 144) /\
      stk xs xm (xp + 152) xhi /\ stk xs xm xlo xp.
  Proof using.
    intros xs xm xlo xb xp xhi xw xj QA QS QC QL QH. clear - QA QS QC QL QH.
    pose proof (stk_of_rw_cells xs xm xb _ QA) as (QR0 & QR1 & _).
