  Lemma mm_CLEAN_B : forall (mq : mem) (hq : HST asegs R HIA) (LBq : list blk) (dTA dW : mpd) (v f r : Z)
      (c0 c8 c16 c24 c32 c40 c48 c56 c64 c72 k120 : word) (gb : list byte) (tp0 ts0 tn0 : Z) (tpad : word)
      (xra t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 s4v s5v s6v s7v s9v s10v : word),
    A_mpi_client.cstateA asegs R HIA h LB LF m (bv_unsigned sp) lo sp1 FB 128 dX es mq hq LBq [dTA] dW
      (CSF (Z_to_bv 64 (FB + 74)) (Z_to_bv 64 (FB + 42)) (Z_to_bv 64 (FB + 64)) (Z_to_bv 64 (FB + 32)) (Z_to_bv 64 FB) k120 gb)
      FSHXL v f ->
    md_addr dTA = FB + 32 ->
    rw_cells asegs mq sp1 (mm_frb c0 c8 c16 c24 c32 c40 c48 c56 c64 c72) ->
    rw_cells asegs mq (FB + 64) [C8 (Z_to_bv 64 tp0); C2 (Z_to_bv 64 ts0); C2 (Z_to_bv 64 tn0); C4 tpad] ->
    uwc asegs mq (arl_stklo R) (hstkhi asegs R HIA h) (bv_unsigned sp) (sp1 + 80) (d + 1) ->
    (r = 0 \/ r = MBEDTLS_ERR_MPI_ALLOC_FAILED) ->
    v + AVOL_CALL <= mul_mpi_PHI dX dA dB ->
    f + fr_charge (d + 1) <= mul_mpi_FR d ->
    havol asegs R HIA h + mul_mpi_PHI dX dA dB <= AVOL_MAX ->
    hfr asegs R HIA h + mul_mpi_FR d <= FR_MAX ->
    md_n dW <= Z.max (md_n dX) (Z.max (md_n dA + md_n dB) 1) ->
    aevtA asegs (KF asegs R HIA hq mo0) POSTM
      (MS (mkR xra (Z_to_bv 64 sp1) gp tp t0 t1 t2 sp (Z_to_bv 64 sp1) a0 a1 a2 a3 a4 a5 a6 a7
               SH9 (Z_to_bv 64 (FB + 64)) s4v s5v s6v s7v (Z_to_bv 64 FB) s9v s10v (Z_to_bv 64 r) t3 t4 t5 t6)
          F (Z_to_bv 64 0x9f1f0) fc None mq (seg_rom asegs))
